import pickle
import hashlib
from typing import Any, Dict, Optional

class RecommendationCache:
    def __init__(self, max_size: int = 10000):
        self.cache: Dict[str, bytes] = {}
        self.max_size = max_size

    def set(self, user_id: str, recommendations: Dict[str, Any]) -> None:
        """Store serialized recommendations for a user."""
        if len(self.cache) >= self.max_size:
            # Simple eviction: remove first key
            self.cache.pop(next(iter(self.cache)))

        # Pickle for maximum speed - no schema validation overhead
        serialized = pickle.dumps(recommendations)
        self.cache[user_id] = serialized

    def get(self, user_id: str) -> Optional[Dict[str, Any]]:
        """Retrieve and deserialize cached recommendations."""
        if user_id in self.cache:
            # Direct deserialization - minimal overhead
            return pickle.loads(self.cache[user_id])
        return None

    def load_from_disk(self, filepath: str) -> None:
        """Load cache from persistent storage."""
        with open(filepath, 'rb') as f:
            # Load entire cache state at startup
            self.cache = pickle.load(f)

    def save_to_disk(self, filepath: str) -> None:
        """Persist cache to disk."""
        with open(filepath, 'wb') as f:
            pickle.dump(self.cache, f)
